using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Configure an API key via AI:ApiKey in appsettings.json, user-secrets, or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<NoteService>();
builder.Services.AddHttpClient("WebSearch");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();
var httpFactory = host.Services.GetRequiredService<IHttpClientFactory>();

// Define tools the agent can call
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up")] string query) =>
        {
            return SearchWebAsync(httpFactory.CreateClient("WebSearch"), query);
        },
        "SearchWeb",
        "Searches the web for a query and returns a summary of the top results. Use this to gather information on a research topic."),

    AIFunctionFactory.Create(
        ([Description("Short title for the note")] string title,
         [Description("Content of the research note")] string content) =>
        {
            noteService.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "SaveNote",
        "Saves a research note with a title and content. Use this to record important findings as you research."),

    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "GetNotes",
        "Returns all saved research notes. Use this to review what has been gathered before writing the final summary."),
};

// Build the agent with the orchestration layer
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Given a topic, you must:
        1. Search the web multiple times using different queries to gather comprehensive information.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information (at least 3-5 searches), review your notes.
        4. Provide a well-structured summary of your findings with key points and sources.
        Be thorough but concise. Always cite what you found in your searches.
        """,
};

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic (or 'quit' to exit): ");
var topic = Console.ReadLine()?.Trim();

while (!string.IsNullOrEmpty(topic) && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 40));

    noteService.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
            Tools = [.. tools],
        },
    };

    try
    {
        await foreach (var message in agent.InvokeStreamingAsync(messages, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError during research: {ex.Message}");
    }

    Console.WriteLine();
    Console.Write("Enter a research topic (or 'quit' to exit): ");
    topic = Console.ReadLine()?.Trim();
}

Console.WriteLine("Goodbye!");

// Web search implementation using HTTP
static async Task<string> SearchWebAsync(HttpClient httpClient, string query)
{
    try
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        httpClient.DefaultRequestHeaders.UserAgent.Clear();
        httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var html = await httpClient.GetStringAsync(url);

        // Extract text snippets from result blocks
        var results = new List<string>();
        var snippetMarker = "result__snippet";
        var idx = 0;

        while (results.Count < 5 && (idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', idx) + 1;
            var end = html.IndexOf('<', start);
            if (start > 0 && end > start)
            {
                var snippet = System.Net.WebUtility.HtmlDecode(html[start..end]).Trim();
                if (snippet.Length > 20)
                {
                    results.Add(snippet);
                }
            }

            idx = end > 0 ? end : idx + 1;
        }

        if (results.Count == 0)
        {
            return $"Search for '{query}' returned no extractable results. Try a different query.";
        }

        return $"Search results for '{query}':\n" +
               string.Join("\n", results.Select((r, i) => $"{i + 1}. {r}"));
    }
    catch (Exception ex)
    {
        return $"Search failed for '{query}': {ex.Message}. Try a different query.";
    }
}

